/**
 * The format-1 regression fixture (Slice 5A; ADR 2026-10-19 D12 addendum):
 * `packages/core/src/__tests__/fixtures/board-v1.json`, a saved board as
 * this build writes it. Every later build must read it whole: format 1 has
 * no migration, so a change that cannot read it is a new format.
 *
 * It is generated by the builder below, never by hand: the every-kind board
 * (`lightboxSavedBoardFixtures`), the production service's measure of ¶1–¶8
 * of "Alice's Adventures in Wonderland" (Lewis Carroll, 1865, public domain)
 * with every reading kind on it, encoded by the production codec. To write
 * it, run this file with `LIGHTBOX_WRITE_BOARD_FIXTURE=1`. Do that only to
 * add a fixture for a new format, under a new name: this one stays as format
 * 1 was written, even when later builds measure the same text differently.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import {
  decodeLightboxBoardFile,
  encodeLightboxBoardFile,
  lightboxBoardOfFile
} from '@/infrastructure/storage/LightboxBoardCodec';
import { LIGHTBOX_BOARD_TILE_KINDS } from '@/infrastructure/storage/LightboxBoardTileCodec';
import { ALICE_TEXT, SAVED_BOARD_PREFIX, everyKindBoard } from '@/__tests__/infrastructure/lightbox/lightboxSavedBoardFixtures';

const FIXTURE = path.resolve(__dirname, '../../fixtures/board-v1.json');
const SAVED_AT = new Date('2026-10-22T14:05:09.123Z');

function readFixture() {
  const json = fs.readFileSync(FIXTURE, 'utf8');
  const decoded = decodeLightboxBoardFile(json);
  if (decoded.kind !== 'board') {
    throw new Error(`board-v1.json does not decode: ${decoded.reason}`);
  }
  return { json, decoded };
}

describe('board-v1.json, the format-1 regression fixture', () => {
  it('comes from the builder: the every-kind Alice board, saved at its fixed time', async () => {
    const { board, text } = await everyKindBoard();
    const built = encodeLightboxBoardFile({ board, text, savedAt: SAVED_AT });
    if (process.env.LIGHTBOX_WRITE_BOARD_FIXTURE === '1') {
      fs.writeFileSync(FIXTURE, built);
    }
    const { decoded } = readFixture();
    // What names this builder's board, stable however later builds measure it.
    expect({
      savedAt: decoded.file.savedAt,
      boardId: decoded.file.board.boardId,
      displayPath: decoded.file.board.sources[0].displayPath,
      capturedAt: decoded.file.board.sources[0].capturedAt,
      text: decoded.file.board.sources[0].text
    }).toEqual({
      savedAt: '2026-10-22T14:05:09.123Z',
      boardId: `board-${SAVED_BOARD_PREFIX}`,
      displayPath: 'Drafts/alice-1.md',
      capturedAt: 1_700_000_000_000,
      text: ALICE_TEXT
    });
  });

  it('reads whole: format 1, its rules, every tile kind, nothing dropped, and writes back byte for byte', () => {
    const { json, decoded } = readFixture();
    expect(decoded.dropped).toBe(0);
    expect([decoded.file.formatVersion, decoded.file.kind]).toEqual([1, 'lightbox-board']);
    expect(decoded.file.board.rules).toEqual({
      paragraphs: 'blank-line-2026-10-19',
      sentences: 'closing-marks-speech-tags-2026-10-21',
      dialogue: 'double-quotes-2026-10-19',
      beingVerbs: 'contractions-next-word-2026-10-21',
      opinionBasis: 'item-data-2026-10-22'
    });
    const kinds = new Set(decoded.file.board.readings.flatMap((group) => group.tiles.map((tile) => tile.kind)));
    expect([...kinds].sort()).toEqual(Object.keys(LIGHTBOX_BOARD_TILE_KINDS).sort());

    const held = lightboxBoardOfFile(decoded.file);
    if (held.kind !== 'board') {
      throw new Error('board-v1.json holds several sources');
    }
    expect(held.text).toBe(ALICE_TEXT);
    expect(encodeLightboxBoardFile({ board: held.board, text: held.text, savedAt: new Date(decoded.file.savedAt) })).toBe(json);
  });
});
